export const weeksAt = (hours, perWeek = 5) =>
  Math.max(1, Math.ceil(hours / perWeek));

/** "1 week" / "5 weeks" */
export const weeksLabel = (hours, perWeek = 5) => {
  const w = weeksAt(hours, perWeek);
  return `${w} week${w === 1 ? "" : "s"}`;
};

