import React, { useEffect, useState } from "react";
import {
  BrainCircuit,
  Briefcase,
  Database,
  Sparkles,
  Workflow,
} from "lucide-react";
import { tracks as ALL_TRACKS, trackById, pathHours } from "./learnData";
import { projects } from "./learnGuide";
import ProjectPreview from "./ProjectPreviews";
import { GOALS, TRACK_PLAIN, GLOSSARY, weeksAt, NEW_ACCENT } from "./routeCopy";
import "./RouteChooserBeginner.css";

/* ============================================================
   🧭 START HERE — goal-first route chooser.
   ------------------------------------------------------------
   Plain sentences instead of jargon tabs. The chosen route is
   DRAWN, not described: one bar split into its tracks (width =
   hours, colour = track), the builds you'll make as the same
   preview drawings the project ladder uses, and every route on
   one hour scale behind "Compare all routes".
   ============================================================ */

const ICON = {
  new: Sparkles,
  ai: BrainCircuit,
  ml: Database,
  job: Briefcase,
  agentic: Workflow,
};

/* Builds from the project ladder that a route actually teaches: every
   stage the build needs is on the route (or in the basics), and at least one
   is on the route itself. Up to four, spread from easiest to hardest. */
const STAGE_TRACK = {};
const indexStages = (allTracks) =>
  allTracks.forEach((t) =>
    t.stages.forEach((s) => {
      STAGE_TRACK[s.id] = t.id;
    })
  );

function buildsFor(trackIds, basicsOnly) {
  const own = new Set(trackIds);
  const fits = projects.filter((pr) => {
    const homes = pr.stages.map((s) => STAGE_TRACK[s]);
    if (basicsOnly) return homes.every((h) => h === "basics");
    return (
      homes.every((h) => own.has(h) || h === "basics") &&
      homes.some((h) => own.has(h))
    );
  });
  if (fits.length <= 4) return fits;
  return [0, 1, 2, 3].map(
    (i) => fits[Math.round((i * (fits.length - 1)) / 3)]
  );
}

indexStages(ALL_TRACKS);

const shortName = (t) =>
  t.title.split(" — ")[0].replace("Retrieval-Augmented Generation", "RAG");

/** One bar, one segment per track, widths proportional to hours. */
function RouteBar({ tracks, progress, onOpen }) {
  const total = tracks.reduce((s, t) => s + t.hours, 0) || 1;
  return (
    <div className="rb-bar" role="group" aria-label="The route, by hours">
      {tracks.map((t, i) => {
        const done = t.stages.filter((s) => progress[s.id]).length;
        return (
          <button
            key={t.id}
            type="button"
            className="rb-seg"
            style={{
              "--t": t.accent,
              flexGrow: t.hours,
              flexBasis: 0,
              "--done": `${(done / t.stages.length) * 100}%`,
            }}
            onClick={() => onOpen(t)}
            title={`${shortName(t)} — ${TRACK_PLAIN[t.id] || t.tagline}`}
          >
            <span className="rb-seg-fill" aria-hidden="true">
              <i />
            </span>
            <span className="rb-seg-n">{i + 1}</span>
            <span className="rb-seg-name">{shortName(t)}</span>
            <span className="rb-seg-h">
              {t.hours}h
              {t.hours / total < 0.14 ? "" : ` · ${t.stages.length} lessons`}
            </span>
          </button>
        );
      })}
    </div>
  );
}

/** Every route on one hour scale, so the overlap and the size are visible. */
function CompareBars({ paths, basics, at, onPick }) {
  const rows = [
    {
      id: "new",
      label: "Basics",
      tracks: basics ? [basics] : [],
      accent: NEW_ACCENT,
    },
    ...paths.map((p) => ({
      id: p.id,
      label: p.label,
      tracks: p.tracks,
      accent: p.accent,
    })),
  ];
  const max = Math.max(
    ...rows.map((r) => r.tracks.reduce((s, t) => s + t.hours, 0))
  );
  return (
    <div className="rb-cmp">
      {rows.map((r) => {
        const h = r.tracks.reduce((s, t) => s + t.hours, 0);
        return (
          <button
            key={r.id}
            type="button"
            className={`rb-cmp-row${at === r.id ? " on" : ""}`}
            onClick={() => onPick(r.id)}
            style={{ "--c": r.accent }}
          >
            <span className="rb-cmp-l">{r.label}</span>
            <span className="rb-cmp-track">
              <span
                className="rb-cmp-bar"
                style={{ width: `${(h / max) * 100}%` }}
              >
                {r.tracks.map((t) => (
                  <i
                    key={t.id}
                    title={shortName(t)}
                    style={{ flexGrow: t.hours, background: t.accent }}
                  />
                ))}
              </span>
            </span>
            <span className="rb-cmp-h">{h}h</span>
          </button>
        );
      })}
      <p className="rb-cmp-key">
        Same colour, same track. The overlap is why switching later costs less
        than you'd think.
      </p>
    </div>
  );
}

export default function RouteChooserGoal({
  paths,
  chosenId,
  progress,
  onChoose,
  onOpenStage,
  onStartPrelude,
  onAskBuddy,
}) {
  // Preselect the newcomer goal so the section opens on a drawing, not
  // five sentences.
  const [at, setAt] = useState(chosenId || "new");
  const [compare, setCompare] = useState(false);
  const [words, setWords] = useState(false);

  useEffect(() => {
    if (chosenId) setAt(chosenId);
  }, [chosenId]);

  const basics = trackById("basics");
  const goal = GOALS.find((g) => g.id === at);
  const path = at && at !== "new" ? paths.find((p) => p.id === at) : null;
  const tracks =
    at === "new" ? [basics].filter(Boolean) : path ? path.tracks : [];
  const hours = tracks.reduce((s, t) => s + t.hours, 0);
  const stages = tracks.flatMap((t) => t.stages);
  const done = stages.filter((s) => progress[s.id]).length;
  const next = stages.find((s) => !progress[s.id]) || stages[0];
  const nextTrack = next && tracks.find((t) => t.stages.includes(next));
  const accent = path ? path.accent : NEW_ACCENT;
  const builds = at
    ? buildsFor(
        tracks.map((t) => t.id),
        at === "new"
      )
    : [];

  const start = () => {
    if (at === "new") onStartPrelude();
    else if (path) onChoose(path.id);
  };
  const openTrack = (t) => onOpenStage(t.stages[0].id, t.id);

  return (
    <section className="lrn-choose rb" id="choose" data-reveal>
      <p className="lrn-eyebrow">01 — Start here</p>
      <h2 className="lrn-h2">Where would you like to start?</h2>
      <p className="rb-lede">
        No AI experience needed. Pick the sentence that sounds most like you —
        you can switch any time, and finished lessons come with you.
      </p>

      <div className="rb-goals" role="radiogroup" aria-label="Your goal">
        {GOALS.map((g) => {
          const p = paths.find((x) => x.id === g.id);
          const h = g.id === "new" ? basics?.hours : p && pathHours(p);
          const Icon = ICON[g.id] || Sparkles;
          return (
            <button
              key={g.id}
              type="button"
              role="radio"
              aria-checked={at === g.id}
              className={`rb-goal${at === g.id ? " on" : ""}`}
              style={{ "--c": p ? p.accent : NEW_ACCENT }}
              onClick={() => setAt(g.id)}
            >
              <span className="rb-goal-ic" aria-hidden="true">
                <Icon size={18} />
              </span>
              <span className="rb-goal-s">{g.sentence}</span>
              <span className="rb-goal-m">
                {g.id === "new" ? "Start here if unsure · " : ""}~{h}h
                {p && p.headline ? " · where I spend my time" : ""}
              </span>
            </button>
          );
        })}
      </div>

      {goal && (
        <div className="rb-detail" key={at} style={{ "--c": accent }}>
          <div className="rb-figs">
            <div>
              <b>{hours}</b>
              <span>hours of study</span>
            </div>
            <div>
              <b>~{weeksAt(hours)}</b>
              <span>weeks at 5 h a week</span>
            </div>
            <div>
              <b>{done > 0 ? `${done}/${stages.length}` : stages.length}</b>
              <span>{done > 0 ? "lessons done" : "lessons"}</span>
            </div>
          </div>

          <p className="rb-k">Your route</p>
          {at === "new" && basics ? (
            <div
              className="rb-bar"
              role="group"
              aria-label="The basics, lesson by lesson"
            >
              {basics.stages.map((st, i) => (
                <button
                  key={st.id}
                  type="button"
                  className="rb-seg"
                  style={{
                    "--t": accent,
                    flexGrow: Math.max(st.hours, 0.4),
                    flexBasis: 0,
                    "--done": progress[st.id] ? "100%" : "0%",
                  }}
                  onClick={() => onOpenStage(st.id, basics.id)}
                  title={st.title}
                >
                  <span className="rb-seg-fill" aria-hidden="true">
                    <i />
                  </span>
                  <span className="rb-seg-n">{i + 1}</span>
                  <span className="rb-seg-name">
                    {st.title.split(" — ")[0]}
                  </span>
                </button>
              ))}
            </div>
          ) : (
            <RouteBar tracks={tracks} progress={progress} onOpen={openTrack} />
          )}

          {builds.length > 0 && (
            <>
              <p className="rb-k">What you'll build</p>
              <div className="rb-builds">
                {builds.map((b) => (
                  <a
                    key={b.id}
                    href="#projects"
                    className="rb-build"
                    onClick={(e) => {
                      e.preventDefault();
                      // Tell the project ladder which build to spotlight
                      window.dispatchEvent(
                        new CustomEvent("learn:pick-project", { detail: b.id })
                      );
                      const el = document.getElementById("projects");
                      if (el)
                        window.scrollBy({
                          top: el.getBoundingClientRect().top - 90,
                          behavior: "smooth",
                        });
                    }}
                  >
                    <span className="rb-build-pic">
                      <ProjectPreview id={b.id} />
                    </span>
                    <span className="rb-build-t">{b.title}</span>
                  </a>
                ))}
              </div>
            </>
          )}

          <div className="rb-end">
            <p className="rb-finish">
              <b>You'll end up with</b> {goal.finish}
            </p>
            <div className="rb-actions">
              <button type="button" className="rb-cta" onClick={start}>
                {at === "new"
                  ? "Start with the basics →"
                  : chosenId === at
                  ? "Showing below ↓"
                  : done > 0
                  ? "Continue →"
                  : "Start this path →"}
              </button>
              {next && nextTrack && (
                <button
                  type="button"
                  className="rb-first"
                  onClick={() => onOpenStage(next.id, nextTrack.id)}
                >
                  {done > 0 ? "Next up" : "First lesson"}:{" "}
                  <b>{next.title.split(" — ")[0]}</b> ({next.hours}h)
                </button>
              )}
            </div>
            {onAskBuddy && (
              <button
                type="button"
                className="rb-buddy"
                onClick={() =>
                  onAskBuddy(
                    `I picked "${goal.sentence}". In plain words, what will I be doing in the first week?`,
                    `Recommended route on screen, in order: ${tracks
                      .map((t) => `${shortName(t)} (~${t.hours}h)`)
                      .join(" → ")}. Total about ${hours} hours. Start with stage ${
                      next ? next.id : ""
                    }.`
                  )
                }
              >
                Ask the study buddy what week one looks like
              </button>
            )}
          </div>
        </div>
      )}

      <div className="rb-more">
        <button
          type="button"
          aria-expanded={compare}
          onClick={() => setCompare((c) => !c)}
        >
          {compare ? "Hide comparison" : "Compare all routes"}
        </button>
        <button
          type="button"
          aria-expanded={words}
          onClick={() => setWords((w) => !w)}
        >
          {words ? "Hide" : "Words you'll meet"}
        </button>
      </div>
      {compare && (
        <CompareBars paths={paths} basics={basics} at={at} onPick={setAt} />
      )}
      {words && (
        <dl className="rb-glossary">
          {GLOSSARY.map(([term, def]) => (
            <div key={term}>
              <dt>{term}</dt>
              <dd>{def}</dd>
            </div>
          ))}
        </dl>
      )}
    </section>
  );
}
