/**
 * Shared client for the portfolio's LLM endpoints.
 *
 * Both endpoints run the same server-side provider chain
 * (Gemini primary → Gemini fallback → Groq → NVIDIA) and the same
 * per-visitor demo limit, so a caller never picks a provider itself.
 *
 *   streamLLM(prompt, { onDelta, signal })  — server-sent events
 *   completeLLM(prompt, { signal })         — one JSON response
 *   askLLM(prompt, opts)                    — stream, falling back to complete
 *
 * A demo-limit refusal throws an Error with code "DEMO_LIMIT" and
 * `retryAfter` seconds; callers should show that, not retry.
 */
import { auth } from "../firebase/config";

const FUNCTIONS = "https://us-central1-portfolio-142b7.cloudfunctions.net";
const STREAM_URL = `${FUNCTIONS}/callGeminiStream`;
const COMPLETE_URL = `${FUNCTIONS}/callGeminiHTTP`;

// The endpoint rejects longer prompts with 413.
export const MAX_PROMPT_CHARS = 16000;

const authHeaders = async () => {
  try {
    const token = await auth.currentUser?.getIdToken();
    return token ? { Authorization: `Bearer ${token}` } : {};
  } catch (e) {
    return {};
  }
};

export const demoLimitError = (retryAfter) => {
  const err = new Error("demo_limit");
  err.code = "DEMO_LIMIT";
  err.retryAfter = Number(retryAfter) || 600;
  return err;
};

const checkLimit = async (res) => {
  if (res.status !== 429) return;
  const body = await res.json().catch(() => ({}));
  throw demoLimitError(body.retryAfter || res.headers.get("Retry-After"));
};

// After one broken stream, skip straight to the single-response call.
let streamBroken = false;

export async function streamLLM(
  prompt,
  { maxTokens = 1024, onDelta, signal } = {}
) {
  if (
    streamBroken ||
    typeof ReadableStream !== "function" ||
    typeof TextDecoder !== "function"
  ) {
    throw new Error("Streaming unavailable");
  }
  try {
    const res = await fetch(STREAM_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...(await authHeaders()) },
      body: JSON.stringify({ prompt, maxTokens }),
      signal,
    });
    await checkLimit(res);
    if (!res.ok || !res.body) throw new Error(`Stream HTTP ${res.status}`);

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    let text = "";
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let sep;
      while ((sep = buffer.indexOf("\n\n")) !== -1) {
        const block = buffer.slice(0, sep);
        buffer = buffer.slice(sep + 2);
        const event = (block.match(/^event:\s*(.+)$/m) || [])[1];
        const data = (block.match(/^data:\s*(.+)$/m) || [])[1];
        if (event === "error") {
          throw new Error(JSON.parse(data || "{}").message || "Stream error");
        }
        if (event === "delta" && data) {
          const piece = JSON.parse(data).text || "";
          text += piece;
          if (onDelta) onDelta(text, piece);
        }
      }
    }
    if (!text) throw new Error("Empty stream");
    return text;
  } catch (e) {
    if (e.code !== "DEMO_LIMIT" && e.name !== "AbortError") streamBroken = true;
    throw e;
  }
}

export async function completeLLM(prompt, { maxTokens = 1024, signal } = {}) {
  const res = await fetch(COMPLETE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...(await authHeaders()) },
    body: JSON.stringify({ prompt, maxTokens }),
    signal,
  });
  await checkLimit(res);
  if (!res.ok) throw new Error(`LLM HTTP ${res.status}`);
  const data = await res.json();
  const text = (data?.candidates?.[0]?.content?.parts || [])
    .map((p) => p?.text || "")
    .join("");
  if (!text) throw new Error("Empty response");
  return text;
}

/** Stream when possible; otherwise (or if the stream breaks) one response. */
export async function askLLM(prompt, opts = {}) {
  try {
    return await streamLLM(prompt, opts);
  } catch (e) {
    if (e.code === "DEMO_LIMIT" || e.name === "AbortError") throw e;
    const text = await completeLLM(prompt, opts);
    if (opts.onDelta) opts.onDelta(text, text);
    return text;
  }
}
