import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import {
  ArrowUp,
  BookOpen,
  Check,
  Copy,
  GraduationCap,
  Hammer,
  HelpCircle,
  Award,
  Briefcase,
  ExternalLink,
  Minus,
  Route,
  ChevronLeft,
  Library,
  Lightbulb,
  Map as MapIcon,
  RotateCcw,
  Sparkles,
  Square,
  X,
} from "lucide-react";
import { askLLM } from "../../services/llmStream";
import { getVisitorIntelligence } from "../../services/visitorIntelligence";
import {
  MODES,
  buildPrompt,
  parseReply,
  stageById,
  refsIn,
} from "./studyBuddyHarness";
import "./StudyBuddy.css";

/* ============================================================
   🧑‍🏫 STUDY BUDDY — an AI tutor that knows this roadmap.
   ------------------------------------------------------------
   Opened from a stage ("Stuck on this?") or from the page entry,
   never as a floating bubble (two assistants already float here).
   The harness (studyBuddyHarness.js) builds the grounded prompt and
   validates the reply; this file is only the conversation UI.
   ============================================================ */

const STORE = "learn.buddy.v1";
const MAX_KEPT = 24;

const readStore = () => {
  try {
    return JSON.parse(sessionStorage.getItem(STORE) || "[]");
  } catch (e) {
    return [];
  }
};
const writeStore = (msgs) => {
  try {
    sessionStorage.setItem(STORE, JSON.stringify(msgs.slice(-MAX_KEPT)));
  } catch (e) {
    /* private mode — the chat still works, it just won't survive a reload */
  }
};

const VERDICT = {
  correct: { label: "Correct", tone: "good" },
  partly: { label: "Partly there", tone: "warn" },
  "not yet": { label: "Not yet", tone: "bad" },
};

const STAGE_MODES = ["explain", "quiz", "build", "resource"];
const MODE_ICON = {
  explain: Lightbulb,
  quiz: HelpCircle,
  build: Hammer,
  resource: Library,
  next: MapIcon,
  roadmap: Briefcase,
};

const REF_ICON = {
  stage: BookOpen,
  path: Route,
  build: Hammer,
  project: Briefcase,
  course: Award,
  page: ExternalLink,
};

/** What a validated reference does when clicked. */
function useRefAction({ onOpenStage, onChoosePath, onOpenBuild }) {
  return (r) => {
    if (r.t === "stage") onOpenStage(r.id, r.track);
    else if (r.t === "path") onChoosePath(r.id);
    else if (r.t === "build") onOpenBuild(r.id);
  };
}

function RefInline({ r, act }) {
  if (r.href)
    return (
      <a className="sb-stage-link" href={r.href}>
        {r.v}
      </a>
    );
  if (r.t === "course")
    return <strong className="sb-course-inline">{r.v}</strong>;
  return (
    <button type="button" className="sb-stage-link" onClick={() => act(r)}>
      {r.v}
    </button>
  );
}

/* The references at the foot of a reply, drawn as chips: one tap to the
   lesson, path, build or case study; courses show where they were applied. */
function RefChips({ refs, act }) {
  if (!refs.length) return null;
  const order = ["path", "stage", "build", "project", "course", "page"];
  const sorted = [...refs].sort((a, b) => order.indexOf(a.t) - order.indexOf(b.t));
  return (
    <div className="sb-chips">
      {sorted.map((r) => {
        const Icon = REF_ICON[r.t] || BookOpen;
        const label =
          r.t === "path"
            ? `Start the ${r.v} path`
            : r.t === "course"
            ? r.v
            : r.v;
        const inner = (
          <>
            <Icon size={14} aria-hidden="true" />
            <span>
              <b>{label}</b>
              {r.t === "course" && <em>{r.issuer} · course I took</em>}
              {r.t === "build" && <em>Hands-on build</em>}
              {r.t === "project" && <em>Production case study</em>}
              {r.t === "stage" && <em>Lesson</em>}
            </span>
          </>
        );
        if (r.t === "course")
          return (
            <a
              key={`${r.t}${r.id}`}
              className={`sb-chip is-${r.t}`}
              href={r.applied ? `/projects/${r.applied}` : "/education"}
              title={
                r.applied
                  ? "See the project it was applied in"
                  : "See it on the education page"
              }
            >
              {inner}
            </a>
          );
        if (r.href)
          return (
            <a key={`${r.t}${r.id}`} className={`sb-chip is-${r.t}`} href={r.href}>
              {inner}
            </a>
          );
        return (
          <button
            key={`${r.t}${r.id}`}
            type="button"
            className={`sb-chip is-${r.t}`}
            onClick={() => act(r)}
          >
            {inner}
          </button>
        );
      })}
    </div>
  );
}

function Reply({ text, graded, onOpenStage, onChoosePath, onOpenBuild }) {
  const parsed = parseReply(text);
  const refs = refsIn(parsed);
  const act = useRefAction({ onOpenStage, onChoosePath, onOpenBuild });
  // The badge only means something on a graded quiz answer.
  const v = graded && parsed.verdict && VERDICT[parsed.verdict];
  return (
    <>
      {v && <span className={`sb-verdict is-${v.tone}`}>{v.label}</span>}
      {parsed.lines.map((parts, i) => {
        // Paragraph spacing comes from CSS; blank lines would double it.
        if (!parts.some((p) => p.t !== "text" || (p.v || "").trim())) return null;
        const first = parts[0];
        const bullet =
          first.t === "text" && /^\s*[-•*]\s+/.test(first.v || "");
        const content = parts.map((p, j) => {
          const v2 =
            j === 0 && bullet && p.t === "text"
              ? p.v.replace(/^\s*[-•*]\s+/, "")
              : p.v;
          if (p.t === "bold") return <strong key={j}>{v2}</strong>;
          if (p.t === "link")
            return (
              <a key={j} href={p.v} target="_blank" rel="noopener noreferrer">
                {p.v.replace(/^https?:\/\/(www\.)?/, "").slice(0, 40)}
              </a>
            );
          if (p.t === "text") return <React.Fragment key={j}>{v2}</React.Fragment>;
          return <RefInline key={j} r={p} act={act} />;
        });
        return bullet ? (
          <p key={i} className="sb-li">
            {content}
          </p>
        ) : (
          <p key={i}>{content}</p>
        );
      })}
      <RefChips refs={refs} act={act} />
    </>
  );
}

export default function StudyBuddy({
  request, // { stageId, mode, message, nonce } | null
  pathId,
  progress,
  theme,
  onClose,
  onOpenStage,
  onChoosePath = () => {},
  onOpenBuild = () => {},
}) {
  const open = Boolean(request);
  const [msgs, setMsgs] = useState(readStore);
  const [stageId, setStageId] = useState(null);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [, setError] = useState("");
  const [awaitingAnswer, setAwaitingAnswer] = useState(false);
  const [note, setNote] = useState("");
  const abortRef = useRef(null);
  const listRef = useRef(null);
  const inputRef = useRef(null);
  const lastNonce = useRef(null);

  useEffect(() => writeStore(msgs.filter((m) => !m.pending)), [msgs]);

  // Keep the newest message in view while it streams in.
  useEffect(() => {
    const el = listRef.current;
    if (el) el.scrollTop = el.scrollHeight;
    // The quick-action row reappears when a reply finishes and shrinks the
    // list, so scroll again once layout has settled.
  }, [msgs, busy]);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => e.key === "Escape" && close();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const close = () => {
    if (abortRef.current) abortRef.current.abort();
    onClose();
  };

  const send = async (
    text,
    { mode = "chat", stage = stageId, ctx = note, typed = false } = {}
  ) => {
    const message = String(text || "").trim();
    if (!message || busy) return;
    const grading = awaitingAnswer && mode === "chat";
    const history = msgs
      .filter((m) => !m.pending && !m.error)
      .map((m) => ({ role: m.role, text: m.text }));
    const prompt = buildPrompt({
      mode,
      stageId: stage,
      pathId,
      progress: progress || {},
      history,
      message,
      grading,
      note: ctx,
    });

    setError("");
    setInput("");
    setBusy(true);
    const id = Date.now();
    setMsgs((m) => [
      ...m,
      { id: id - 1, role: "user", text: message },
      { id, role: "buddy", text: "", pending: true, graded: grading },
    ]);
    // Only what the learner typed is a question worth recording; button
    // starters ("Quiz me on…") and quiz answers would flood the dashboard.
    if (typed && !grading) {
      try {
        getVisitorIntelligence().trackAIInteraction(message, {
          source: "study_buddy",
        });
      } catch (e) {
        /* tracking is best-effort */
      }
    }

    const ctrl = new AbortController();
    abortRef.current = ctrl;
    try {
      const full = await askLLM(prompt, {
        // Some backup providers count reasoning tokens against this cap;
        // the prompt already limits answer length.
        maxTokens: mode === "roadmap" ? 1800 : 1200,
        signal: ctrl.signal,
        onDelta: (sofar) =>
          setMsgs((m) =>
            m.map((x) => (x.id === id ? { ...x, text: sofar } : x))
          ),
      });
      setMsgs((m) =>
        m.map((x) => (x.id === id ? { ...x, text: full, pending: false } : x))
      );
      // A quiz question waits for the learner's answer; a graded answer
      // that came back correct may carry a follow-up question.
      const verdict = parseReply(full).verdict;
      setAwaitingAnswer(
        mode === "quiz" || (grading && verdict === "correct" && /\?\s*$/.test(full.trim()))
      );
    } catch (e) {
      const msg =
        e.name === "AbortError"
          ? "Stopped."
          : e.code === "DEMO_LIMIT"
          ? `The study buddy has a per-visitor limit and it's been reached for now. Try again in about ${Math.max(
              1,
              Math.round((e.retryAfter || 600) / 60)
            )} min — the stages, resources and self-checks all still work without it.`
          : "I couldn't reach the model just now. Please try again in a moment.";
      setMsgs((m) =>
        m.map((x) =>
          x.id === id
            ? x.text && e.name === "AbortError"
              ? { ...x, pending: false }
              : { ...x, text: msg, pending: false, error: true }
            : x
        )
      );
      if (e.code === "DEMO_LIMIT") setError(msg);
    } finally {
      setBusy(false);
      abortRef.current = null;
    }
  };

  // A new request from the page: set the stage, run its mode or message.
  useEffect(() => {
    if (!request || request.nonce === lastNonce.current) return;
    lastNonce.current = request.nonce;
    try {
      localStorage.setItem("learn.buddy.seen", "1");
    } catch (e) {
      /* fine */
    }
    const sid = request.stageId || null;
    setStageId(sid);
    const ctx = request.context || "";
    setNote(ctx);
    setAwaitingAnswer(false);
    const entry = sid && stageById(sid);
    if (request.message)
      send(request.message, { mode: "chat", stage: sid, ctx });
    else if (request.mode && MODES[request.mode].starter && entry)
      send(MODES[request.mode].starter(entry), {
        mode: request.mode,
        stage: sid,
        ctx,
      });
    else setTimeout(() => inputRef.current && inputRef.current.focus(), 50);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [request]);

  if (!open) return null;
  const entry = stageId && stageById(stageId);
  const shortT = entry ? entry.stage.title.split(" — ")[0] : "";
  const firstBasics = stageById("tokens");

  // Quick starts on the empty screen: one tap, no typing.
  const QUICK = [
    {
      icon: Briefcase,
      title: "I'm switching to AI",
      sub: "A roadmap for software engineers",
      run: () => send(MODES.roadmap.starter(), { mode: "roadmap", stage: null }),
    },
    {
      icon: Lightbulb,
      title: "Explain a concept",
      sub: "What is an LLM, in plain words?",
      run: () => send("What is an LLM, in plain words?"),
    },
    {
      icon: HelpCircle,
      title: "Quiz me",
      sub: "A quick question on the basics",
      run: () =>
        firstBasics &&
        (setStageId("tokens"),
        send(MODES.quiz.starter(firstBasics), { mode: "quiz", stage: "tokens" })),
    },
    {
      icon: MapIcon,
      title: "Plan my week",
      sub: "What should I study next?",
      run: () => send(MODES.next.starter(), { mode: "next", stage: null }),
    },
  ];

  const stageModes = entry
    ? STAGE_MODES.filter((k) => k !== "build" || entry.stage.build)
    : [];

  return createPortal(
    <div className="sb-root" data-theme={theme?.name || "dark"}>
      <div className="sb-backdrop" onClick={close} />
      <aside
        className="sb-sheet"
        role="dialog"
        aria-modal="true"
        aria-label="Study buddy"
      >
        <header className="sb-head">
          <span className="sb-avatar" aria-hidden="true">
            <GraduationCap size={20} />
          </span>
          <div className="sb-head-t">
            <h2>Study buddy</h2>
            <p>
              <span className={`sb-status${busy ? " is-busy" : ""}`} />
              {busy ? "Thinking…" : "AI tutor for this roadmap"}
            </p>
          </div>
          {msgs.length > 0 && !busy && (
            <button
              type="button"
              className="sb-icon-btn"
              onClick={() => {
                setMsgs([]);
                setAwaitingAnswer(false);
                setError("");
              }}
              title="New chat"
              aria-label="Start a new chat"
            >
              <RotateCcw size={16} />
            </button>
          )}
          <button
            type="button"
            className="sb-icon-btn"
            onClick={close}
            aria-label="Close study buddy"
            title="Close (Esc)"
          >
            <X size={18} />
          </button>
        </header>

        <div className="sb-context">
          <BookOpen size={14} aria-hidden="true" />
          {entry ? (
            <>
              <span>
                On <b>{shortT}</b>
              </span>
              <button type="button" onClick={() => setStageId(null)}>
                Ask about anything
              </button>
            </>
          ) : (
            <span>Whole roadmap</span>
          )}
        </div>

        <div className="sb-list" ref={listRef} aria-live="polite">
          {msgs.length === 0 && (
            <div className="sb-empty">
              <span className="sb-empty-icon" aria-hidden="true">
                <Sparkles size={22} />
              </span>
              <h3>Hi, I'm your study buddy</h3>
              <p>
                Ask in your own words — no question is too basic. I explain
                in plain language, quiz you, and point you to the right lesson.
              </p>
              <div className="sb-quick">
                {(entry
                  ? stageModes.map((k) => ({
                      icon: MODE_ICON[k],
                      title: MODES[k].label,
                      sub: shortT,
                      run: () =>
                        send(MODES[k].starter(entry), { mode: k, stage: stageId }),
                    }))
                  : QUICK
                ).map((q) => {
                  const Icon = q.icon;
                  return (
                    <button key={q.title} type="button" onClick={q.run}>
                      <Icon size={17} aria-hidden="true" />
                      <span>
                        <b>{q.title}</b>
                        <em>{q.sub}</em>
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}
          {msgs.map((m) => (
            <div
              key={m.id}
              className={`sb-msg is-${m.role}${m.error ? " is-error" : ""}`}
            >
              {m.role === "buddy" && (
                <span className="sb-msg-av" aria-hidden="true">
                  <GraduationCap size={14} />
                </span>
              )}
              <div className="sb-msg-body">
                {m.role === "buddy" ? (
                  m.text ? (
                    <>
                      <Reply
                        text={m.text}
                        graded={m.graded}
                        onOpenStage={onOpenStage}
                        onChoosePath={onChoosePath}
                        onOpenBuild={onOpenBuild}
                      />
                      {!m.pending && !m.error && <CopyBtn text={m.text} />}
                    </>
                  ) : (
                    <span className="sb-typing" aria-label="Thinking">
                      <i />
                      <i />
                      <i />
                    </span>
                  )
                ) : (
                  <p>{m.text}</p>
                )}
              </div>
            </div>
          ))}
        </div>

        {!busy && msgs.length > 0 && (
          <div className="sb-modes" aria-label="Quick actions">
            {(entry ? stageModes : ["roadmap", "next"]).map((k) => {
              const Icon = MODE_ICON[k];
              return (
                <button
                  key={k}
                  type="button"
                  onClick={() =>
                    k === "next" || k === "roadmap"
                      ? send(MODES[k].starter(), { mode: k, stage: null })
                      : send(MODES[k].starter(entry), { mode: k, stage: stageId })
                  }
                >
                  <Icon size={14} aria-hidden="true" />
                  {MODES[k].label}
                </button>
              );
            })}
          </div>
        )}

        <form
          className="sb-form"
          onSubmit={(e) => {
            e.preventDefault();
            send(input, { typed: true });
          }}
        >
          <div className="sb-composer">
            <textarea
              ref={inputRef}
              rows={1}
              value={input}
              maxLength={1200}
              placeholder={
                awaitingAnswer ? "Type your answer…" : "Ask anything about AI…"
              }
              onChange={(e) => {
                setInput(e.target.value);
                const t = e.target;
                t.style.height = "auto";
                t.style.height = `${Math.min(140, t.scrollHeight)}px`;
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  send(input, { typed: true });
                }
              }}
            />
            {busy ? (
              <button
                type="button"
                className="sb-send is-stop"
                onClick={() => abortRef.current && abortRef.current.abort()}
                aria-label="Stop"
                title="Stop"
              >
                <Square size={14} />
              </button>
            ) : (
              <button
                type="submit"
                className="sb-send"
                disabled={!input.trim()}
                aria-label="Send"
                title="Send (Enter)"
              >
                <ArrowUp size={18} />
              </button>
            )}
          </div>
        </form>
        <p className="sb-foot">
          Can be wrong — check it against the linked resources. Powered by
          Gemini, with Groq and NVIDIA as backups.
        </p>
      </aside>
    </div>,
    document.body
  );
}

/** Small copy-to-clipboard for a reply. */
function CopyBtn({ text }) {
  const [done, setDone] = useState(false);
  return (
    <button
      type="button"
      className="sb-copy"
      onClick={() => {
        const ok = () => {
          setDone(true);
          setTimeout(() => setDone(false), 1600);
        };
        if (navigator.clipboard?.writeText)
          navigator.clipboard
            .writeText(text.replace(/\[\[stage:[^\]]+\]\]/g, ""))
            .then(ok, ok);
      }}
      aria-label="Copy answer"
    >
      {done ? <Check size={13} /> : <Copy size={13} />}
      {done ? "Copied" : "Copy"}
    </button>
  );
}

/**
 * Always-there quick start on the right edge of /learn (the bottom corners
 * already hold Jarvis and the chat orb). Press "b" anywhere outside a text
 * field to open it.
 *
 * - First visit: shown in full, with a gentle pulse, until the buddy has
 *   been opened once (from here, the B key or any "Stuck on this?" button).
 * - After that: still full, but with a minimise control; minimised, it
 *   tucks into a slim tab that slides out on hover. The choice is remembered.
 */
const SEEN = "learn.buddy.seen";
const MIN = "learn.buddy.min";
const readFlag = (k) => {
  try {
    return localStorage.getItem(k) === "1";
  } catch (e) {
    return false;
  }
};
const writeFlag = (k, on) => {
  try {
    if (on) localStorage.setItem(k, "1");
    else localStorage.removeItem(k);
  } catch (e) {
    /* storage blocked — the launcher still works for this visit */
  }
};

export function StudyBuddyLauncher({ onOpen, hidden }) {
  const [seen, setSeen] = useState(() => readFlag(SEEN));
  const [min, setMin] = useState(() => readFlag(MIN));

  // The sheet marks "seen" on any open; pick that up when it closes.
  useEffect(() => {
    if (!hidden) setSeen(readFlag(SEEN));
  }, [hidden]);

  useEffect(() => {
    const onKey = (e) => {
      if (hidden) return; // already open — don't reset its context
      const tag = (e.target && e.target.tagName) || "";
      if (
        e.key.toLowerCase() === "b" &&
        !e.metaKey &&
        !e.ctrlKey &&
        !e.altKey &&
        !/INPUT|TEXTAREA|SELECT/.test(tag) &&
        !(e.target && e.target.isContentEditable)
      ) {
        e.preventDefault();
        onOpen();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onOpen, hidden]);

  if (hidden) return null;
  const tucked = seen && min;
  return (
    <div
      className={`sb-launch${seen ? "" : " is-new"}${tucked ? " is-min" : ""}`}
    >
      <button
        type="button"
        className="sb-launch-main"
        onClick={() => {
          writeFlag(SEEN, true);
          setSeen(true);
          onOpen();
        }}
        aria-label="Open the study buddy (press B)"
        title="Study buddy — press B"
      >
        <GraduationCap size={18} aria-hidden="true" />
        <span className="sb-launch-t">
          <b>Study buddy</b>
          <em>{seen ? "Ask me anything" : "New to AI? Ask me anything"}</em>
        </span>
      </button>
      {seen && !tucked && (
        <button
          type="button"
          className="sb-launch-min"
          onClick={() => {
            writeFlag(MIN, true);
            setMin(true);
          }}
          aria-label="Minimise the study buddy button"
          title="Minimise"
        >
          <Minus size={14} />
        </button>
      )}
      {tucked && (
        <button
          type="button"
          className="sb-launch-min is-restore"
          onClick={() => {
            writeFlag(MIN, false);
            setMin(false);
          }}
          aria-label="Show the full study buddy button"
          title="Keep it expanded"
        >
          <ChevronLeft size={14} />
        </button>
      )}
    </div>
  );
}
